<?php require '../includes/bootstrap.php';student_required();if($_SERVER['REQUEST_METHOD']!=='POST')redirect('../student/problems.php');$sid=(int)$_SESSION['student_id'];$pid=(int)$_POST['problem_id'];try{$pdo->beginTransaction();$p=$pdo->prepare("SELECT p.* FROM problem_statements p JOIN events e ON e.event_id=p.event_id WHERE p.problem_id=? AND p.status='AVAILABLE' AND e.status='OPEN' FOR UPDATE");$p->execute([$pid]);$problem=$p->fetch();if(!$problem)throw new Exception('Problem is not available for selection.');$count=selected_count($pdo,$pid);if($count >= (int)$problem['max_teams'])throw new Exception('This problem has reached capacity.');$old=$pdo->prepare("SELECT * FROM selections WHERE student_id=? FOR UPDATE");$old->execute([$sid]);$sel=$old->fetch();if($sel){$oldPid=(int)$sel['problem_id'];$pdo->prepare("UPDATE selections SET problem_id=?,selected_at=CURRENT_TIMESTAMP,status='SELECTED' WHERE student_id=?")->execute([$pid,$sid]);$pdo->prepare("INSERT INTO selection_history(student_id,old_problem_id,new_problem_id,action_type,notes) VALUES(?,?,?,'CHANGED','Changed by student')")->execute([$sid,$oldPid,$pid]);}else{$pdo->prepare("INSERT INTO selections(student_id,problem_id,status) VALUES(?,?,'SELECTED')")->execute([$sid,$pid]);$pdo->prepare("INSERT INTO selection_history(student_id,new_problem_id,action_type,notes) VALUES(?,?,'SELECTED','Initial selection')")->execute([$sid,$pid]);}$pdo->commit();flash('success','Problem selection saved.');}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();flash('error',$e->getMessage());}redirect('../student/dashboard.php');
